action.code:
if (root == nullptr) {
    return;
}

if (root->left == nullptr && root->right == nullptr) {
    int symbol = root->symbol;
    for (int i = 0; i < pathLen; ++i) {
        codes[symbol][i] = path[i];
    }
    codes[symbol][pathLen] = -1; // Mark end of code
    ++codeCount;
    return;
}

if (root->left != nullptr) {
    path[pathLen] = 0;
    huffmanGenerateCodes(root->left, path, pathLen + 1, codes, codeCount);
}

if (root->right != nullptr) {
    path[pathLen] = 1;
    huffmanGenerateCodes(root->right, path, pathLen + 1, codes, codeCount);
}
// END_CODE

